#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str

baseb = list("abcdefghijklmnopqrstuvwxyz")

N = 0


def solve(S: str, T: str):
    from collections import Counter

    s = Counter(S)
    t = Counter(T)

    if sorted(s.values()) == sorted(t.values()):
        print("Yes")
    else:
        print("No")
    return
    return


# Generated by 1.1.3 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    T = next(tokens)  # type: str
    solve(S, T)


if __name__ == '__main__':
    main()
